  "auto.liveNotice": "Переключить в режим в эфире?\n\nПри включённой автоматизации Aurora будет передавать сама: отвечать на CQ по заданным правилам и включать «Разрешить TX» (по окончании автоматизации всё вернётся как было).\n\nВы остаётесь ответственным за каждую передачу: вы должны находиться рядом или иметь возможность вмешаться, как того требует ваша лицензия. STOP TX, ограничения, заданные на ПК, и выключение при отсутствии устройства остаются в силе.\n\nУчитывайте правила дипломов: ARRL и DXCC не принимают полностью автоматические QSO.",
