  "ctest.statusTip": "Активный контест текстового режима: щелчок — список контестов",
  "ctest.tip.autoInc": "Порядковый номер увеличивается на единицу после каждого сохранённого QSO.",
  "ctest.tip.bandMult": "Вкл.: мультипликаторы считаются на каждом диапазоне. Отмеченный диапазон с весом больше нуля засчитывает каждый свой мультипликатор с этим весом; остальные — по одному.",
  "ctest.tip.dates": "Начало и конец контеста в UTC. QSO вне этого периода никогда не являются дублями. Даты повторяются каждый год: учитываются день и время; пусто = без ограничения.",
  "ctest.tip.domain": "Список провинций, штатов или зон (папка contest/dom).",
  "ctest.tip.export": "Сохраняет выбранный контест в пакет .zip вместе с его макросами и списком областей, чтобы передать другим.",
  "ctest.tip.grabNumber": "Номер после позывного в принятом тексте сам попадает в поле принятого номера, если оно пусто.",
  "ctest.tip.grabState": "Принятое слово, найденное в списке областей, само попадает в поле принятого номера, если оно пусто.",
  "ctest.tip.grabType": "Что подставлять в принятый обмен: порядковый номер из принятого текста или зону CQ или ITU введённого позывного (вид SSB).",
  "ctest.tip.import": "Добавляет контест из пакета .zip (файл .contest с его макросами) или из файла .contest. Файл проверяется и не заменяет ни один контест.",
  "ctest.tip.macros": "Макросы контеста (папка contest/macros). Они заменяют макросы режима на той же клавише.",
  "ctest.tip.merge": "Вкл.: макросы режима остаются на клавишах, которые контест не использует. Выкл.: только макросы контеста.",
  "ctest.tip.mult": "Два выбранных типа мультипликаторов складываются. Счёт = очки · мультипликаторы (без мультипликаторов: только очки).",
  "ctest.tip.mySect": "Отправляется после номера (например, 001 ACC) в контестах, где станция также должна передавать район, клуб или штат; иначе не используется. Запоминается для этого контеста на этом компьютере.",
  "ctest.tip.noBand": "Вкл.: один и тот же позывной считается дублем на любом диапазоне.",
  "ctest.tip.noMode": "Вкл.: один и тот же позывной считается дублем в любом режиме.",
  "ctest.tip.nrs": "С автоувеличением это первый номер (001, если пусто); без него это фиксированный обмен, отправляемый через <NRS> (зона, провинция…).",
  "ctest.tip.points": "Очки за QSO: та же страна, тот же континент, другие континенты. Все нули = одно очко за QSO. Дубли стоят ноль.",
  "ctest.tip.propose": "Задаёт начало и конец издания этого года (последние полные выходные месяца контеста, с 00:00:00 до 23:59:59 UTC). Перед сохранением проверьте правила.",
  "ctest.tip.qtc": "В контесте есть QTC WAE: счёт их учитывает, в Cabrillo есть строки QTC и открывается окно QTC (макросы <QTCSEND> и <QTCREAD>)",
  "ctest.tip.stored": "Хранится в файле контеста; Aurora не использует это для подсчёта очков.",
  "ctest.tip.suggest": "Показывает значение под позывным по мере ввода (из базы префиксов); щелчок вставляет его в принятый обмен.",
  "ctest.tip.valid": "Категории видов связи, которые засчитываются. Если ничего не отмечено, засчитываются все. QSO в незасчитываемых категориях никогда не являются дублями.",
  "ctest.tip.workTime": "Часы работы, разрешённые правилами (0 = без ограничения). Только напоминание.",
