  "digi.band.validation": "Проверка",
  "digi.band.validationTip": "Насколько строго проверять позывные. Aurora подсчитывает форматы позывных каждой страны (префикс, цифры, буквы суффикса) по журналу, спотам DX Cluster и файлу MASTER.SCP, если он есть: обычный формат встречается не менее чем у 1% позывных страны, необычный — от 0,05% до 1%, подозрительный — реже. Минимальная: достаточно формы. Обычная: существующая страна DXCC, подозрительные — только если слышны несколько раз. Строгая: без подозрительных, необычные — только если подтверждены. Максимальная: только подтверждённые позывные обычного формата. Серии, не назначенные ITU, всегда отбрасываются.",
