  "dxs.bands": "Диапазоны для показа",
  "dxs.bandsTip": "Столбцы карточки. Нужен хотя бы один. U охватывает диапазоны короче 4 метров.",
  "dxs.bg": "Фон",
  "dxs.captions": "Показывать подписи под метками",
  "dxs.captionsTip": "Три мелкие строки (страна, диапазон и режим с позывным) под шестью метками.",
  "dxs.cellTip": "Цвет квадрата: {kind}, в режиме {mode}.",
  "dxs.cellsOf": "Квадраты {mode}",
  "dxs.colors": "Цвета",
  "dxs.colorsHelp": "У каждого режима свои цвета, поэтому FT8 и FT4 можно различить по подтверждениям. Кнопка ↺ возвращает заводской цвет (цвет светлой или тёмной темы).",
  "dxs.compact": "Компактный размер",
  "dxs.compactTip": "Ячейки, подписи и интервалы меньше, больше места для журнала. Выключено: обычный размер.",
  "dxs.factory": "Заводской цвет",
  "dxs.guide.bands": "Диапазоны и строки: отметьте диапазоны и режимы, которые хотите видеть в карточке (нужен хотя бы один диапазон). «DIG» объединяет остальные цифровые режимы (RTTY, PSK, JT65...). Выбор применяется сразу и сохраняется при перезапуске.",
  "dxs.guide.colors": "Цвета: для каждого режима выберите три цвета для квадратов (проведено, не подтверждено, никогда не проводилось) и для каждой подписи четыре цвета (фон и текст, вкл и выкл). Кнопка ↺ рядом с цветом возвращает заводское значение; «Вернуть заводские цвета» возвращает все. Квадрат всегда имеет контур, даже если выбран цвет, совпадающий с фоном.",
  "dxs.guide.grid": "Сетка: одна строка на режим, один столбец на диапазон. Зелёный квадрат = вы уже проводили связь со страной станции на этом диапазоне и в этом режиме; оранжевый = проведено, но не подтверждено; пусто = никогда. Крупное число — общее количество проведённых стран.",
  "dxs.guide.labels": "Шесть подписей: NEW ONE = страна ещё не проводилась; NEW BAND = страна проводилась, но не на этом диапазоне; NEW MODE = страна проводилась, но не в этом режиме. NEW GRID, GRID BAND и GRID MODE — то же самое для локатора (квадрат из 4 символов). Они окрашиваются цветами «вкл», когда относятся к станции, иначе остаются «выкл».",
  "dxs.guide.title": "Как это работает",
  "dxs.guide.what": "Карточка DXCC (под журналом, на странице Станция) показывает для вызываемой станции, новая ли её страна и на каких диапазонах и в каких режимах вы уже с ней проводили связи. Данные берутся из журнала Aurora и из внешней программы, подключённой в Настройках (например, Log4OM2).",
  "dxs.ink": "Текст",
  "dxs.intro": "Выберите, что показывает карточка DXCC и в каких цветах. Изменения применяются сразу, сохраняются в программе и остаются после перезапуска.",
  "dxs.labelTip": "{part} подписи {label}, {state}.",
  "dxs.labelsOf": "Подпись {label}",
