  "dxs.off": "выкл",
  "dxs.on": "вкл",
  "dxs.preview": "Предпросмотр (тестовые данные)",
  "dxs.resetColors": "Вернуть заводские цвета",
  "dxs.resetColorsTip": "Удаляет все выбранные цвета: карточка возвращается к цветам темы. Диапазоны, строки и оформление остаются.",
  "dxs.rows": "Строки (режимы) для показа",
  "dxs.rowsTip": "FT8 и FT4 — отдельные режимы. DIG объединяет остальные цифровые режимы (JT65, JT9, RTTY...): по умолчанию выключен.",
  "dxs.total": "Показывать общее число проведённых стран",
