  "dxs.tryFieldTip": "Поле, где вводится позывной, чтобы увидеть, как карточка его оценивает.",
  "ens.adv.help": "Декодер Aurora собственный (модули ft8/ft4) и не использует эти параметры, поэтому здесь ничего менять не нужно.",
  "ens.applied": "Применено: Aurora уже использует новые значения.",
  "ens.appliedRestart": "Сохранено. Часть изменений вступит в силу при следующем запуске Aurora (пункты с отметкой «с следующего запуска»); остальное уже действует.",
  "ens.apply": "Применить",
  "ens.audio.help": "Вход и выход выбираются здесь и сохраняются после перезапуска. Уровень входа (громкость записи Windows) следует за выбранным устройством и регулируется по индикатору RX.",
  "ens.audio.help.sys": "Вход и выход выбираются здесь и сохраняются после перезапуска. Уровень входа задаётся в системном микшере.",
  "ens.discard": "Отменить изменения",
  "ens.dxsummit.help": "Спот DXSummit никогда не уходит сам по себе: он отправляется кнопкой «Spot DX» на панели команд страницы «Станция» (при выбранной станции DX), с частотой радио, частотой приёма и режимом в комментарии. Один раз на станцию, только из домашней сети.",
