  "ens.n.jt_only": "Относится только к JT65, JT9 и T10: в FT8 и FT4 составной позывной отправляется в сообщениях в угловых скобках, и эта настройка ничего не меняет.",
  "ens.note": "Это настройки Aurora, сохраняемые в её собственном файле ({file}) с резервной копией. Aurora применяет их сразу, без перезапуска, если не указано иное. Только с домашнего ПК.",
