  "ens.r.alert_files": "Программа проигрывает выбранный вами аудиофайл как отдельное оповещение; Aurora использует собственные звуки и оповещения («Нужные» и «Уведомления») и не открывает системные аудиофайлы.",
  "ens.r.all_txt_pending": "В Aurora пока недоступно: ALL.TXT записывается всегда; переключатель пока не подключён (AURORA_ALL_TXT=0 отключает его при запуске).",
