  "ens.r.cw_id": "CW-идентификатор передаётся только в режимах JT и WSPR, никогда в FT8 или FT4; Aurora передаёт только FT8 и FT4 и не имеет CW-манипулятора.",
  "ens.r.decode52": "Относится только к режимам JT (JT65, JT9, T10), которые декодируют на 52-й секунде минуты; FT8 и FT4 этого не используют.",
  "ens.r.dxsummit": "Выключено: кнопки «Spot DX» пока нет на странице (спот отправляется только по нажатию); служба уже готова в ядре.",
