  "ens.r.false_spots": "В Aurora пока недоступно: декодер Aurora не выдаёт сообщения с сомнительными позывными, поэтому исключать нечего (нужно проверить на большем объёме данных).",
  "ens.r.log_auto": "Пока всегда включено: связь записывается автоматически; ручная запись появится вместе с окном подтверждения.",
