  "ens.r.psk": "В Aurora пока недоступно: отправка спотов в PSK Reporter ещё не реализована (в планах).",
  "ens.r.radio_cat": "Радиостанция и PTT задаются в «Настройки → Станция → Радио».",
  "ens.r.screen_off": "Пока не доступно в Aurora: список сообщений имеет собственную фиксированную раскладку (в планах).",
  "ens.r.tcp": "В Aurora пока недоступно: нет TCP-сервера для записей ADIF (у Aurora есть собственный HTTP API и отправка по UDP).",
