  "ens.r.udp_filters": "Выключено: фильтры хранятся в браузере и пока не скопированы в Aurora; отправитель UDP уже может их применять.",
  "ens.r.udp_window": "Выключено: окно приложения Windows выводилось бы на передний план, но связи с окном пока нет.",
  "ens.r.upload_secrets": "Выключено: для хранения ключей и паролей нужна защита секретов Windows (в этой системе недоступна).",
  "ens.radio.help": "Со встроенным движком радио, последовательный порт и PTT задаются в «Настройки → Станция → Радио»: отсюда ничего не берётся из файла другой программы.",
  "ens.rep.help": "Каждая записанная связь сохраняется в журнале Aurora и в его файле ADIF. Вторичный UDP-сервер получает запись ADIF (например, Log4OM2): Aurora отправляет её только один раз, даже если тот же адрес задан в другом месте.",
