  "ens.st.title": "Последняя отправка",
  "ens.svc.on": "Вкл",
  "ens.tcp.help": "Отправляет каждую записанную связь в журнал по TCP, например в N1MM Logger+.",
  "ens.test": "Тест",
  "ens.test.err": "проверка не пройдена",
  "ens.test.ok": "проверка пройдена",
  "ens.test.running": "Проверка…",
  "ens.test.saveFirst": "проверка выполняется после сохранения изменений",
  "ens.title": "Настройки Aurora",
  "ens.udp.help": "Основной UDP-сервер принимает декодирование и статус (GridTracker, JTAlert). Входящие запросы могут заставить Aurora ответить или передать сигнал.",
  "ens.unavailable": "Настройки недоступны.",
  "ens.up.clublog.help": "Каждая записанная связь сразу уходит в Club Log (в реальном времени, по одной связи). Простой способ: в Club Log откройте «Settings → API», создайте токен (он начинается с cl_ и показывается только один раз) и вставьте его сюда; «Тест» действительно проверяет токен, не отправляя связи. Если вы уже пользуетесь старым способом, можно оставить e-mail, пароль приложения и ключ API: когда задан токен, он имеет приоритет. При неверном токене или учётных данных отправка сразу останавливается и возобновляется, когда вы их исправите.",
  "ens.up.hamqth.help": "HamQTH — бесплатная база позывных: достаточно зарегистрироваться на hamqth.com. Aurora использует её, когда поиск на QRZ.com выключен или не находит позывной: без подписки QRZ XML это способ получить имя и город. Те же правила: только имя, город и страна, результаты хранятся три дня, при выключении запросов нет. «Проверка» открывает сеанс.",
  "ens.up.hrdlog.help": "Каждое записанное QSO сразу уходит в ваш журнал на HRDLOG.NET, с той же очередью и повторами, что и у других сервисов. Нужны позывной журнала и «код загрузки», который HRDLOG.NET показывает в вашем профиле. У HRDLOG.NET нет проверки без отправки: «Проверка» только убеждается, что данные есть; код проверяется с первым QSO.",
  "ens.up.lotw.help": "Aurora сама не подписывает: она использует TQSL, установленный на ПК, с вашим сертификатом и расположением станции, созданным в TQSL (введите здесь то же название). TQSL ищется в обычных папках; если он в другом месте, укажите путь к tqsl.exe. Сертификат не должен запрашивать пароль (иначе TQSL остановится). Ожидающие связи уходят вместе одной отправкой; дубликаты и связи вне дат действия сертификата пропускаются. «Тест» проверяет TQSL и расположение, ничего не отправляя.",
  "ens.up.qrz.help": "Каждая записанная связь сразу уходит в ваш журнал на QRZ.com. Ключ находится в настройках журнала на QRZ.com; вставка через API требует подписки QRZ. Дубликаты не перезаписывают уже имеющиеся связи. «Тест» запрашивает у QRZ состояние журнала, ничего не записывая.",
  "ens.up.qrzlookup.help": "Когда вы наводите курсор на позывной в DX Cluster, Aurora запрашивает у QRZ.com имя и город этой станции. Нужны ваши имя пользователя и пароль QRZ.com (не ключ журнала). С подпиской «XML Logbook Data» QRZ возвращает полные данные; без неё — только урезанные (часто только имя и страна). Показываются только имя, город и страна, никогда не e-mail и адрес. Результаты хранятся в памяти три дня; при выключении запросы не отправляются. «Проверка» открывает сеанс и показывает, активна ли подписка.",
  "ens.up.wavelog.help": "Каждая записанная связь сразу уходит в Wavelog или Cloudlog (тот же API). Адрес — тот, по которому вы открываете сайт (с /index.php или без него). Ключ API создайте в меню пользователя, пункт «API»: он должен быть ключом на чтение и запись. Выберите номер станции из списка, заполненного станциями, считанными с сервера (ключ должен быть сохранён). «Тест» проверяет ключ и станцию без записи в журнал. Если сети нет, связи остаются в очереди и повторяются автоматически.",
  "ens.wl.noList": "Станции не считаны: проверьте адрес и ключ API (сохранённые), затем повторите или введите номер.",
  "ens.wl.pick": "Выберите станцию",
  "ens.wl.read": "Считать станции с сервера",
  "ens.wl.reading": "Чтение…",
  "ens.wl.unknown": "нет на сервере",
  "ens.wsprnet.help": "Как в WSJT-X «Upload spots», по умолчанию выключено: когда выключено, ничего не отправляется. Когда включено, после каждого принятого периода WSPR или FST4W Aurora отправляет на wsprnet.org (по http, без шифрования) один отчёт на каждый декодированный сигнал: позывной, локатор и мощность передающей станции, время, отчёт S/N, сдвиг по времени, дрейф и частоту, а также ваш позывной, ваш локатор, частоту приёма, версию Aurora и режим. Если в периоде ничего нет, отправляется только статус станции, в котором есть также частота передачи, «Tx Pct» и мощность маяка. Споты становятся публичными на сайте WSPRnet. Нужна частота радио (CAT); если WSPRnet не отвечает, повторные попытки длятся не более одного часа.",
  "err.badText": "Неверный текст: не более 13 символов — буквы, цифры и + - . / ?",
  "err.bandHopEmpty": "Список Band Hopping пуст: заполните его в Настройки › Режимы › FT8 › FT4 › Последовательность.",
