  "err.gone": "Это сообщение больше недоступно.",
  "err.noRig": "Трансивер не подключён: подключите его в Настройки › Станция › Радио (CAT).",
  "err.rig": "Трансивер не отвечает: проверьте связь CAT в Настройки › Станция › Радио.",
