  "int.err.wait": "Исправьте отмеченные значения: пока они неверны, список не сохраняется.",
  "int.help": "Другие программы, которые принимают данные от Aurora: для каждой выберите, что отправлять. Адрес многоадресной рассылки (например, 239.255.0.1) позволяет нескольким программам слушать вместе на одном порту. Команды, приходящие обратно (ответ, цвета, Clear, Location, Configure), работают только при включённом «Принимать запросы UDP».",
