  "newlog.intro": "У Aurora есть собственный внутренний журнал, работающий с первой установки: каждое QSO записывается туда, а из него берутся проведённые станции, новые страны DXCC, статистика и карта. При желании можно также подключить внешний журнал (Log4OM, ниже) или импортировать свою историю из файла ADIF (страница файлов ADIF). «Новый пустой журнал» начинает всё с нуля.",
