  "not.color": "Цвет",
  "not.highlight": "Подсветка",
  "not.intro": "Для каждого типа сообщения: цвет, подсвечивать ли его и проигрывать ли звук. Типы такие же, как в Aurora.",
  "not.kind": "Тип",
  "not.restoreColors": "Вернуть цвета Aurora",
  "not.sound": "Звук",
  "not.soundHelp": "Звуки воспроизводятся только если включены звуковые оповещения и после касания страницы (правило браузера).",
  "not2.alertDx": "Оповещение о позывном DX",
  "not2.alertHelp": "Оповещения проигрывают выбранный звук для: вызова меня, выбранного позывного DX, новой зоны CQ/ITU, страны, локатора или префикса (а при «по диапазону» — нового на диапазоне или в режиме этого типа). «По диапазону» соответствует полям выше: срабатывает, если в сообщении есть эта метка. «Также звуком» — это обычный короткий сигнал. Они работают только при включённых «Звуковых оповещениях» и открытой странице; во время передачи молчат. Браузер требует нажатия на страницу, прежде чем что-либо проиграть.",
  "not2.alertMy": "Оповещение о моём позывном",
