  "not2.grpAlerts": "Оповещения и звуки",
  "not2.grpColors": "Цвета и предпросмотр",
  "not2.grpDisplay": "Вид сообщений",
  "not2.grpMapColors": "Карта DX",
  "not2.grpTable": "Выделения и звуки по типам",
  "not2.grpWorked": "Уже работанные",
  "not2.help": "«Уже работанная» — это только позывной, который действительно есть в вашем журнале и не является новым ни для одного включённого выделения: станция, с которой вы никогда не работали, никогда не считается «уже работанной», даже если её страна или зона такие. Если ни одно выделение не включено, «уже работанной» тоже нет. «По диапазону» и «по режиму» определяют, что считается выполненным: только диапазон = тот же диапазон в любом режиме, только режим = тот же режим на любом диапазоне, оба = тот же диапазон и тот же режим (FT8 и FT4 — разные режимы). Новизна вычисляется по журналу Aurora, файлам ADIF и Log4OM2, как на карточке DXCC. Выделения применяются при нажатии «Применить»; отображение уже работанных сообщений применяется сразу на этом устройстве.",
