  "radio.control": "Управление со страницы (OmniRig)",
  "radio.help": "Aurora управляет трансивером через OmniRig. Aurora использует тот же OmniRig, чтобы менять диапазон и нажимать кнопки Aurora, не отбирая у него радио. Последовательный порт, PTT, управление потоком (handshake) и режим задаются в Aurora (Настройки › Станция › Радио). Чтобы включить управление отсюда, запустите Aurora с AURORA_RIG=omnirig.",
  "radio.off": "Не активно (AURORA_RIG=none)",
  "radio.on": "Активно",
  "radio.sharing": "Совместное использование радио",
  "radio.swr.hint": "Если трансивер показывает КСВ выше этого значения во время передачи, Aurora сразу прекращает передачу и сообщает вам (по умолчанию 2,5; для лучшей защиты используйте 2,0). Требуется CAT Hamlib с чтением КСВ. 0 = проверка выключена.",
  "radio.swr.title": "Защита передатчика (КСВ)",
