  "rbn.enabled": "Получать споты RBN",
  "rbn.enabledTip": "По умолчанию выключено. Когда включено, Aurora подключается к telnet.reversebeacon.net под позывным станции.",
  "rbn.feed": "Порт {port}: {state}, спотов: {n}",
  "rbn.help": "Споты от автоматических приёмников RBN: кто вызывает CQ в CW, RTTY, FT8 и FT4 и сколько приёмников его слышат. Aurora входит под позывным станции. На страницах CW и RTTY они появляются на водопаде с меткой RBN и рядом с Aurora BIGScan.",
