  "rep.active": "Отправлять статистику",
  "rep.activeTip": "При запуске, а затем примерно каждые 40 минут, пока Aurora открыта, отправляется: уровень использования (простаивает, принимает, передаёт), случайный код установки или, если вы указали позывной, код, полученный из позывного (сам позывной никогда не отправляется), версия Aurora, операционная система, название установленного антивируса, страна и тип компьютера (процессор, число ядер и память). Это нужно, чтобы считать пользователей Aurora и понимать, на каких компьютерах она работает с трудом. Никогда не позывные, никогда не IP-адреса.",
  "rep.ask": "Спрашивать, отправить ли отчёт после сбоя",
  "rep.auto": "Отправлять отчёты об ошибках автоматически (анонимно)",
  "rep.autoHint": "По каждой серьёзной ошибке отправляется короткий отчёт: версия, система, антивирус, движок, модель радио, PTT, CAT, звуковая карта, область и очищенное сообщение. Одна и та же ошибка — не более одного раза в час, не более {max} в день.",
  "rep.close": "Закрыть",
  "rep.countries": "Стран: {n}",
  "rep.crashSend": "Отправить отчёт",
  "rep.crashText": "Aurora закрылась из-за ошибки. Отправить отчёт тому, кто разрабатывает Aurora? В нём только очищенный журнал и отчёты о сбоях, без персональных данных.",
  "rep.crashTitle": "Aurora закрылась из-за ошибки",
  "rep.cty": "Страны DXCC (cty.dat)",
  "rep.export": "Экспорт QSO во внешние журналы",
  "rep.failed": "Не удалось отправить ({message}).",
  "rep.file": "Файл ADIF",
  "rep.forward": "Идентичная пересылка на",
  "rep.help": "Каждое записанное QSO сохраняется в журнале Aurora и отправляется сюда. Aurora уже отправляет QSO в Log4OM2 через свой вторичный UDP-сервер: не добавляйте того же получателя, иначе записи задублируются. Задаётся через AURORA_EXPORT_UDP и AURORA_EXPORT_FILE.",
  "rep.id": "Анонимный ID этой установки",
  "rep.intro": "По умолчанию включено, можно отключить. Отчёты помогают тому, кто разрабатывает Aurora, находить и исправлять проблемы. Перед отправкой удаляются позывные, локаторы, сообщения, IP-адреса, адреса электронной почты, пароли и имя пользователя.",
