  "sat.uplink.hint": "Aurora переключается на второй VFO («Sub»; если радио не принимает его, то «VFO B»), записывает частоту и режим передачи и возвращается на VFO приёма, с интервалами: каждое переключение VFO может давать треск в радио. Если радио отклоняет команду, резервный режим выключается сам и сообщает об этом. Спутниковый режим радио (SUB), если Hamlib может его включить, пробуется один раз; иначе включите его вручную. Пока радио передаёт, VFO не меняется.",
