  "sdr.radiosText": "TCI: SunSDR2 (Pro, DX, QS) и ColibriNANO с ExpertSDR2/3, ANAN и Hermes-Lite 2 с Thetis. Для QMAP также нужен поток I/Q из TCI (или файл I/Q WAV). Для обычных трансиверов (FT-2000, IC-7300…) эта страница не нужна.",
  "sdr.tci": "Связь TCI",
  "sdr.useAll": "Использовать TCI для всего",
  "sdr.useAllAsk": "CAT переключается на TCI ({address}), а аудиовход и аудиовыход — на «TCI (dalla radio)» и «TCI (alla radio)». Ваши прежние выборы радио и звука будут заменены. Продолжить?",
  "send.clublog_denied": "Club Log отказал в доступе ({detail}); отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки. Проверьте email, пароль приложения (App Password), позывной журнала и ключ API либо используйте токен Club Log",
  "send.clublog_duplicate": "QSO с {calls} уже есть в Club Log{d}",
  "send.clublog_off": "Club Log выключен в настройках; отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки",
  "send.clublog_rejected": "QSO с {calls} отвергнуто Club Log: {detail}",
  "send.clublog_rejected.plain": "QSO с {calls} отвергнуто Club Log: неверные данные",
  "send.clublog_rejected_status": "QSO с {calls} отвергнуто Club Log (ответ {detail})",
  "send.clublog_retry_http": "Club Log ответил {detail}: следующая попытка в {time} UTC",
  "send.clublog_retry_network": "{detail}: следующая попытка в {time} UTC",
  "send.clublog_secrets_missing": "Пароль или ключ API Club Log не заданы; отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки",
  "send.clublog_sent": "QSO с {calls} отправлено в Club Log{d}",
  "send.clublog_token_denied": "Club Log не принимает токен ({detail}): создайте новый в Club Log › Settings › API и вставьте его в настройки; отправка приостановлена (QSO остаются в очереди)",
  "send.hrdlog_call_missing": "Не указан позывной журнала HRDLOG.NET: введите его в поле «Позывной журнала»; отправка приостановлена (QSO остаются в очереди)",
  "send.hrdlog_code_missing": "Код загрузки HRDLOG.NET не задан; отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки",
  "send.hrdlog_denied": "HRDLOG.NET отклонил позывной или код загрузки ({detail}); отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки. Нужен «Код загрузки» из профиля HRDLOG.NET, а не пароль.",
  "send.hrdlog_duplicate": "QSO с {calls} уже есть на HRDLOG.NET{d}",
  "send.hrdlog_off": "HRDLOG.NET выключен в настройках; отправка приостановлена (QSO остаются в очереди), пока вы не измените настройки",
