  "send.hrdlog_unreadable": "Ответ HRDLOG.NET не понят ({detail}): следующая попытка в {time} UTC",
  "send.upload_expired": "QSO с {calls} отброшено: в очереди более семи дней",
  "seq.intro": "Когда и кому отвечать автоматически. Выключено и работает в режиме пробного запуска: реальную передачу можно включить только с ПК.",
  "seq.link": "Открыть страницу автоматизации",
  "seq2.answerAll": "Отвечать на каждую станцию, которая вызывает меня (очередь)",
  "seq2.answerB4": "Отвечать уже работанным (Answer B4)",
  "seq2.answerCq": "отвечаете на CQ и никто не отвечает",
  "seq2.answerInCall": "вызываете CQ, получаете вызов и отвечаете",
  "seq2.autoseq": "Автоматическая последовательность (AutoSeq)",
  "seq2.group": "Среди декодированных сообщений вызывать CQ или прекращать передачу, если:",
  "seq2.haltReplyOther": "Прекратить передачу, если корреспондент, которого вы вызываете, ответил другому",
  "seq2.help": "Число — максимум передач одного и того же сообщения: следующая передача не начинается, и последовательность возвращается к поиску среди CQ или останавливается. Не относится к нужным станциям и новым DXCC (вы продолжаете их вызывать). «Стоп Tx…» прерывает передачу, когда DX говорит с кем-то другим; если выключено, останавливается, только когда он говорит близко к вашей частоте. «Строгий CQ» соблюдает направление CQ (CQ NA, CQ DX…) также для нужных станций и новых DXCC. Изменения применяются сразу, без перезапуска.",
  "seq2.maxDist": "Приоритет наибольшего расстояния",
  "seq2.prioCq": "Приоритет CQ",
  "seq2.rules": "Правила Aurora (автоответ)",
  "seq2.sentRR7373": "отправить RR73 (73) в ответ на RRR (RR73)",
  "seq2.sentRReport": "отправить отчёт в ответ на полученный отчёт",
  "seq2.single": "Одиночное QSO",
  "seq2.skipTx1": "Пропустить Tx1",
  "seq2.stop": "Вызов и остановка",
  "seq2.strictCq": "Строгая работа на CQ",
  "seq2.switchHelp": "AutoSeq, «Одиночное QSO», «Пропустить Tx1» и «Отвечать уже работанным» — те же переключатели, что и на панели QSO: здесь и там вы видите и меняете одно и то же состояние (запоминается при перезапуске). «Приоритет CQ» также ищет CQ других станций для вызова (AutoSeq 6 и 7); «наибольшее расстояние» выбирает самую дальнюю станцию при прочих равных. Оба приоритета применяются кнопкой «Применить».",
  "seq2.switches": "Последовательность и выбор, кого вызывать",
  "seq2.times": "раз",
  "seq2.title": "Последовательность сообщений для коротких сценариев",
