  "snd.fileFail": "Файл не загружен: до 5 MB, WAV, MP3 или OGG",
  "snd.help": "Каждая функция имеет свой звук, выбираемый здесь или в строке типа сообщения выше: разный звук для каждой или «Нет». Функция звучит, только если у неё есть звук и включено её оповещение («также звук», «Звук оповещения», «звук при первом сообщении»); выбор звука включает оповещение. Если срабатывают две функции сразу, звучит самая важная. Все звуки создаются программой, файлов нет. Громкость общая; «не играть при передаче» действует на все, кроме «Моё переданное сообщение», которое и есть сигнал Tx. Кнопка «Назначить разные звуки» заполняет функции, но не включает оповещения.",
